// Generates the Logto custom-JWT-claims script from the configured customData keys,
// so config/sso.config.json stays the single source of truth for mapped claims.
export const accessTokenScript = (keys) => `/**
 * Generated by scripts/provision.js from config/sso.config.json (customJwtClaims.fromCustomData).
 * Do not edit in the Logto Console; re-run \`npm run provision\` instead.
 */
const getCustomJwtClaims = async ({ token, context, environmentVariables }) => {
  const customData = (context && context.user && context.user.customData) || {};
  const claims = {};
  for (const key of ${JSON.stringify(keys)}) {
    if (customData[key] !== undefined) claims[key] = customData[key];
  }
  return claims;
};`;
